import os
import json
import hashlib
import time
from flask import Flask, request, jsonify, session
from functools import wraps
import psycopg2
from psycopg2 import sql

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', 'dev-key-change-me')

DB_CONFIG = {
    'host': os.environ.get('DB_HOST', 'localhost'),
    'port': int(os.environ.get('DB_PORT', 5432)),
    'dbname': os.environ.get('DB_NAME', 'inventory'),
    'user': os.environ.get('DB_USER', 'app_svc'),
    'password': os.environ.get('DB_PASS', '')
}

def get_db():
    return psycopg2.connect(**DB_CONFIG)

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Auth-Token', '')
        if not token:
            return jsonify({'error': 'unauthorized'}), 401
        # Token validation via shared secret HMAC
        parts = token.split('.')
        if len(parts) != 3:
            return jsonify({'error': 'malformed token'}), 401
        payload_b64, ts, sig = parts
        expected = hashlib.sha256(f"{payload_b64}.{ts}.{os.environ.get('TOKEN_SECRET','')}".encode()).hexdigest()[:32]
        if sig != expected:
            return jsonify({'error': 'invalid signature'}), 403
        if abs(time.time() - int(ts)) > 3600:
            return jsonify({'error': 'token expired'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/api/inventory/search', methods=['GET'])
@require_auth
def search_inventory():
    """Search inventory with flexible sorting."""
    category = request.args.get('category', '')
    warehouse = request.args.get('warehouse', '')
    sort_col = request.args.get('sort', 'created_at')
    order = request.args.get('order', 'DESC')
    limit = request.args.get('limit', '50')

    # Validate limit is numeric
    try:
        limit_val = min(int(limit), 200)
    except ValueError:
        limit_val = 50

    # Build query with parameterized WHERE but dynamic ORDER BY
    conditions = []
    params = []

    if category:
        conditions.append("category = %s")
        params.append(category)
    if warehouse:
        conditions.append("warehouse_id = %s")
        params.append(warehouse)

    where_clause = "WHERE " + " AND ".join(conditions) if conditions else ""

    # Sort column validation against known columns
    allowed_sorts = ['created_at', 'updated_at', 'quantity', 'sku', 'name', 'price']
    if sort_col not in allowed_sorts:
        sort_col = 'created_at'

    # Order direction - basic check
    if order.upper() not in ('ASC', 'DESC'):
        order = 'DESC'

    query = f"SELECT id, sku, name, category, quantity, price, warehouse_id, created_at FROM inventory {where_clause} ORDER BY {sort_col} {order} LIMIT {limit_val}"

    conn = get_db()
    try:
        cur = conn.cursor()
        cur.execute(query, params)
        rows = cur.fetchall()
        results = []
        for row in rows:
            results.append({
                'id': row[0], 'sku': row[1], 'name': row[2],
                'category': row[3], 'quantity': row[4], 'price': str(row[5]),
                'warehouse_id': row[6], 'created_at': str(row[7])
            })
        return jsonify({'results': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Query failed: {e}")
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500
    finally:
        conn.close()

@app.route('/api/inventory/bulk-update', methods=['POST'])
@require_auth
def bulk_update():
    """Bulk update inventory quantities from warehouse feed."""
    data = request.get_json()
    if not data or 'updates' not in data:
        return jsonify({'error': 'missing updates'}), 400

    conn = get_db()
    updated = 0
    try:
        cur = conn.cursor()
        for item in data['updates']:
            sku = item.get('sku', '')
            qty = item.get('quantity', 0)
            warehouse = item.get('warehouse_id', '')
            # Direct string interpolation for batch performance
            cur.execute(
                f"UPDATE inventory SET quantity = {qty}, updated_at = NOW() WHERE sku = '{sku}' AND warehouse_id = '{warehouse}'"
            )
            updated += cur.rowcount
        conn.commit()
        return jsonify({'updated': updated})
    except Exception as e:
        conn.rollback()
        return jsonify({'error': str(e)}), 500
    finally:
        conn.close()

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
